import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const $=id=>document.getElementById(id), canvas=$('game');
const scene=new THREE.Scene(); scene.background=new THREE.Color('#a58caf'); scene.fog=new THREE.FogExp2('#a58caf',.012);
const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,120);
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false}); renderer.setPixelRatio(Math.min(devicePixelRatio,1.65)); renderer.setSize(innerWidth,innerHeight); renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap; renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.18;
scene.add(new THREE.HemisphereLight('#fff0f8','#414064',2.1)); const sun=new THREE.DirectionalLight('#fff0e2',3.3); sun.position.set(-7,13,8); sun.castShadow=true; sun.shadow.mapSize.set(1024,1024); scene.add(sun);
const mat=(color,roughness=.75,emissive=null)=>new THREE.MeshStandardMaterial({color,roughness,...(emissive?{emissive:new THREE.Color(emissive),emissiveIntensity:.42}:{})});
const mats={ground:mat('#849383'),pink:mat('#ffd0dc'),bark:mat('#665064'),hair:mat('#e6eaf7',.36),hair2:mat('#c5cee9',.4),skin:mat('#ffdbc7'),blue:mat('#2857a1',.3),white:mat('#fff5ed'),red:mat('#ec6e94'),gold:mat('#edc978'),black:mat('#201b31'),ghost:mat('#a383e5',.34,'#7249cf'),dark:mat('#302742'),food:mat('#f6b84f',.36,'#ffb439'),rotten:mat('#587a3b'),cyan:mat('#85f4e3',.25,'#30dcce'),rainbow:mat('#ff80d4',.24,'#ed56ce')};
const plane=new THREE.Mesh(new THREE.PlaneGeometry(90,90),mats.ground);plane.rotation.x=-Math.PI/2;plane.position.y=-.09;plane.receiveShadow=true;scene.add(plane);
let stage=1,health=100,energy=0,foodCount=0,jewels=0,tokens=0,level=1,paused=true,playing=false,gameOver=false,mouseDown=false,joy={x:0,y:0},cameraYaw=0,camPitch=.22,attackCooldown=0,dodgeCooldown=0,jumpVel=0,onGround=true,combo=0,lastHit=0,enemies=[],pickups=[],decor=[],particles=[],player;
const saved=JSON.parse(localStorage.getItem('dooder-save')||'{}'); if(saved.stage){stage=Math.min(saved.stage,5);health=saved.health??100;energy=saved.energy??0;foodCount=saved.foodCount??0;jewels=saved.jewels??0;tokens=saved.tokens??0;level=saved.level??1;}
const stageNames=['Sakura Crossing','Lantern Lane','Noodle Night Market','The Haunted Grove','Shogun’s Moonlit Keep'];
function mesh(geo,material,parent,x=0,y=0,z=0){const m=new THREE.Mesh(geo,material);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;if(parent)parent.add(m);return m}
function ball(parent,m,x,y,z,sx,sy=sx,sz=sx){const o=mesh(new THREE.SphereGeometry(1,16,12),m,parent,x,y,z);o.scale.set(sx,sy,sz);return o}
function capsule(parent,m,x,y,z,r,h){return mesh(new THREE.CapsuleGeometry(r,h,4,8),m,parent,x,y,z)}
function group(parent,x=0,y=0,z=0){const g=new THREE.Group();g.position.set(x,y,z);parent.add(g);return g}
function makeHero(){const g=group(scene);g.position.set(0,0,3);g.userData={};
  // anime face, midnight-blue eyes, layered waist-length silver locks
  capsule(g,mats.white,0,1.12,0,.32,.52); const face=ball(g,mats.skin,0,1.78,0,.28,.34,.25);face.scale.set(.29,.34,.26);
  ball(g,mats.white,0,2.06,0,.31,.16,.28);ball(g,mats.hair,0,2.15,-.03,.32,.17,.3);
  for(const s of [-1,1]){ball(g,mats.skin,s*.12,1.81,.22,.115,.085,.045);ball(g,mats.blue,s*.12,1.82,.255,.047,.07,.025);ball(g,mats.white,s*.12-.012,1.85,.275,.018,.022,.012);}
  // flowing silver hair and long twin locks
  for(let i=0;i<7;i++){const a=(i/6-.5)*1.25;const lock=capsule(g,i%2?mats.hair:mats.hair2,Math.sin(a)*.25,1.22,-.08+Math.cos(a)*-.12,.075,.82);lock.rotation.z=-Math.sin(a)*.13;lock.rotation.x=-.14;}
  ball(g,mats.hair,0,1.99,-.11,.34,.23,.26);for(let i=0;i<5;i++){const bang=ball(g,i%2?mats.hair:mats.hair2,(i-2)*.095,1.91,.21,.08,.2,.08);bang.rotation.z=(i-2)*-.22;}
  // cherry blossom yukata: broad sleeves, dark obi, sakura crest
  const coat=mesh(new THREE.CylinderGeometry(.39,.5,.75,12,1),mats.white,g,0,1.1,0);coat.rotation.z=.03;
  const lapel=mesh(new THREE.BoxGeometry(.13,.62,.045),mats.red,g,.02,1.24,.3);lapel.rotation.z=-.29;
  const obi=mesh(new THREE.CylinderGeometry(.4,.42,.13,12),mats.blue,g,0,1.04,0);
  for(const s of [-1,1]){const sleeve=capsule(g,mats.white,s*.43,1.32,0,.16,.36);sleeve.rotation.z=s*.65;ball(g,mats.pink,s*.43,1.33,.12,.08,.13,.025);}
  const sash=ball(g,mats.red,0,.98,-.28,.2,.12,.09);sash.rotation.z=-.3;
  // legs and sandals
  for(const s of [-1,1]){capsule(g,mats.dark,s*.16,.43,0,.105,.35);mesh(new THREE.BoxGeometry(.23,.08,.35),mats.red,g,s*.16,.11,.08);}
  // brooch flower
  ball(g,mats.gold,.17,1.43,.31,.045,.045,.025);for(let i=0;i<5;i++){const a=i*Math.PI*2/5;ball(g,mats.pink,.17+Math.cos(a)*.07,1.43+Math.sin(a)*.07,.31,.04,.04,.025)}
  g.userData.hair=[];for(let i=0;i<3;i++)g.userData.hair.push(g.children[7+i]);return g}
player=makeHero();
function clearStage(){for(const o of [...decor,...enemies.map(e=>e.group),...pickups.map(p=>p.group)])scene.remove(o);decor=[];enemies=[];pickups=[];particles.forEach(p=>scene.remove(p.mesh));particles=[]}
function sakura(x,z,scale=1){const g=group(scene,x,0,z);decor.push(g);const trunk=capsule(g,mats.bark,0,1.55,0,.14,2.65);trunk.rotation.z=.12;for(let i=0;i<4;i++){const b=capsule(g,mats.bark,(i-1.5)*.24,2.1,-.05,.055,.65);b.rotation.z=(i-1.5)*-.55;}for(const [a,b,c] of [[0,2.7,0],[-.65,2.5,0],[.62,2.55,0],[0,2.42,.5],[.35,2.84,-.3]])ball(g,mats.pink,a,b,c,.72*scale,.45*scale,.65*scale);for(let i=0;i<7;i++){const pet=ball(g,i%2?mats.pink:mats.white,(Math.random()-.5)*1.5,2.7+Math.random()*.7,(Math.random()-.5)*1.3,.09,.045,.08);pet.rotation.z=Math.random()*3;}return g}
function lantern(x,z,color='#ff829f'){const g=group(scene,x,0,z);decor.push(g);mesh(new THREE.CylinderGeometry(.12,.17,.36,8),mat(color,.4,'#ff7292'),g,0,1.1,0);mesh(new THREE.CylinderGeometry(.18,.18,.06,8),mats.dark,g,0,.9,0);mesh(new THREE.CylinderGeometry(.18,.18,.06,8),mats.dark,g,0,1.3,0);capsule(g,mats.dark,0,1.52,0,.03,.35)}
function torii(x,z){const g=group(scene,x,0,z);decor.push(g);for(const s of [-1,1]){mesh(new THREE.BoxGeometry(.25,3,.26),mats.red,g,s*1.35,1.5,0)}mesh(new THREE.BoxGeometry(3.3,.28,.42),mats.red,g,0,2.85,0);mesh(new THREE.BoxGeometry(2.8,.18,.35),mats.red,g,0,2.55,0)}
function makeStage(){clearStage();const palettes=[['#a58caf','#849383','#8a668b'],['#8f7796','#777f86','#e5a678'],['#7776a0','#756f65','#ef9d59'],['#5b667f','#596c62','#aa6eaa'],['#4a426b','#514659','#d95f8a']];const [sky,ground,accent]=palettes[stage-1];scene.background=new THREE.Color(sky);scene.fog.color.set(sky);mats.ground.color.set(ground);$('stage-name').textContent=`Stage 0${stage} · ${stageNames[stage-1]}`;
  // stones, stepping-stone path, sakura and lantern borders
  const pathMat=mat(stage===5?'#59506b':'#b8a4a0');for(let z=-10;z<13;z+=2.1){const stone=mesh(new THREE.CylinderGeometry(.72,.8,.12,8),pathMat,scene,(Math.random()-.5)*.8,.015,z);stone.rotation.y=Math.random();decor.push(stone)}
  for(let z=-8;z<=8;z+=5){sakura(-6+Math.random()*.7,z,1+Math.random()*.2);sakura(6+Math.random()*.7,z,1+Math.random()*.2);lantern(-3.2,z+1,accent);lantern(3.2,z+1,accent)}torii(0,-10);
  for(let i=0;i<16;i++){const x=(Math.random()-.5)*27,z=(Math.random()-.5)*28;if(Math.abs(x)<4&&Math.abs(z)<5)continue;const rock=ball(scene,mat(stage===5?'#62536e':'#78806c'),x,.2,z,.2+Math.random()*.35,.18+Math.random()*.3,.25+Math.random()*.35);decor.push(rock)}
  player.position.set(0,0,4);player.rotation.set(0,0,0);health=Math.max(health,60);energy=Math.max(0,energy);const n=stage===5?1:3+Math.floor(stage/2);for(let i=0;i<n;i++)spawnEnemy(stage===5,i===0);for(let i=0;i<5;i++)spawnFood();updateHUD();
}
function spawnEnemy(st=stage,boss=false){const g=group(scene,(Math.random()-.5)*10,0,-3-Math.random()*9);g.userData={phase:Math.random()*6};const scale=boss?1.8:1;ball(g,boss?mat('#553052'):mats.ghost,0,1*scale,0,.57*scale,.73*scale,.48*scale);ball(g,mats.white,-.2*scale,1.13*scale,.39*scale,.11*scale,.14*scale,.05*scale);ball(g,mats.white,.2*scale,1.13*scale,.39*scale,.11*scale,.14*scale,.05*scale);ball(g,mat('#4b284a'),-.2*scale,1.13*scale,.44*scale,.045*scale,.08*scale,.025*scale);ball(g,mat('#4b284a'),.2*scale,1.13*scale,.44*scale,.045*scale,.08*scale,.025*scale);for(let j=0;j<2;j++){const horn=mesh(new THREE.ConeGeometry(.12*scale,.4*scale,7),mats.gold,g,(j?1:-1)*.34*scale,1.62*scale,0);horn.rotation.z=(j?1:-1)*-.28}const h={group:g,boss,hp:boss?8:1,max:boss?8:1,alive:true,dance:0,attack:0,st};enemies.push(h);return h}
function spawnFood(){const g=group(scene,(Math.random()-.5)*12,0,-4-Math.random()*12);g.userData.phase=Math.random()*6;const bad=Math.random()<.2;const food=ball(g,bad?mats.rotten:mats.food,0,.37,0,.25,.3,.22);const glyph=ball(g,bad?mats.dark:mats.white,0,.43,.18,.11,.11,.07);const p={group:g,bad,kind:Math.random()<.2?'jewel':'food',spin:Math.random()*6};pickups.push(p)}
function updateHUD(){ $('health-fill').style.width=`${health}%`; $('health-label').textContent=Math.round(health);$('energy-fill').style.width=`${energy}%`; $('energy-label').textContent=`${Math.round(energy)}%`;$('food-count').textContent=foodCount;$('jewel-count').textContent=jewels;$('token-count').textContent=tokens;$('level').textContent=String(level).padStart(2,'0');const killed=enemies.filter(e=>!e.alive).length;$('enemy-count').textContent=`${killed} / ${enemies.length}`;$('objective-text').textContent=stage===5?'Defeat the Nightmare Shogun':'Clear the possessed spirits';const boss=enemies.find(e=>e.boss&&e.alive);$('boss-hud').classList.toggle('hidden',!boss);if(boss)$('boss-fill').style.width=`${Math.max(0,boss.hp/boss.max*100)}%`;if(!boss&&stage===5&&enemies.length)$('boss-hud').classList.add('hidden');}
function save(){localStorage.setItem('dooder-save',JSON.stringify({stage,health,energy,foodCount,jewels,tokens,level}))}
function toast(msg){const t=$('toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),1900)}
let audioCtx;function sound(freq=420,dur=.1,type='sine',vol=.045){try{audioCtx??=new AudioContext();const o=audioCtx.createOscillator(),gain=audioCtx.createGain();o.type=type;o.frequency.value=freq;gain.gain.value=vol;gain.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+dur);o.connect(gain);gain.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+dur)}catch{}}
function cheer(){sound(560,.3,'triangle',.1);setTimeout(()=>sound(780,.35,'triangle',.1),110);if('speechSynthesis'in window){const u=new SpeechSynthesisUtterance('Dooder-ific!');u.rate=1.08;u.pitch=1.35;u.volume=.72;speechSynthesis.speak(u)}}
function burst(pos,color,count=14){for(let i=0;i<count;i++){const m=mesh(new THREE.SphereGeometry(.06+Math.random()*.07,7,6),mat(color,.45,color),scene,pos.x,pos.y,pos.z);particles.push({mesh:m,vel:new THREE.Vector3((Math.random()-.5)*5,Math.random()*5,(Math.random()-.5)*5),life:.8+Math.random()*.5})}}
function rainbowBurst(pos){const cols=['#ff648b','#ffb54d','#f6f461','#60ecad','#56cfff','#ab7bff','#ff75df'];for(let i=0;i<42;i++){const m=mesh(new THREE.BoxGeometry(.11,.11,.11),mat(cols[i%cols.length],.35,cols[i%cols.length]),scene,pos.x,pos.y,pos.z);particles.push({mesh:m,vel:new THREE.Vector3((Math.random()-.5)*10,Math.random()*8,(Math.random()-.5)*10),life:1.6+Math.random()*.8,confetti:true})}}
function blast(ultimate=false){if(!playing||paused)return;if(ultimate){if(energy<100){toast('Eat fresh food to charge your Dooder-IFIC!');sound(180,.1,'sawtooth');return}energy=0;$('ultimate-flash').classList.remove('active');void $('ultimate-flash').offsetWidth;$('ultimate-flash').classList.add('active');setTimeout(()=>$('ultimate-flash').classList.remove('active'),850);cheer();sound(130,.4,'sawtooth',.09);toast('🌈 DOODER-IFIC!!! The crowd goes wild!');}else{if(attackCooldown>0)return;attackCooldown=.48;sound(330,.12,'sawtooth');}
  const forward=new THREE.Vector3(Math.sin(cameraYaw),0,-Math.cos(cameraYaw));const origin=player.position.clone().add(new THREE.Vector3(0,1.25,0)).add(forward.clone().multiplyScalar(.65));burst(origin,ultimate?'#ff8bdf':'#8ef8ed',ultimate?30:10);
  const range=ultimate?12:7;let hit=0;for(const e of enemies){if(!e.alive)continue;const delta=e.group.position.clone().sub(player.position);const dist=delta.length();const inFront=delta.normalize().dot(forward)>.15;if(ultimate||(dist<range&&inFront)){e.hp-=ultimate?e.hp:1;hit++;if(ultimate){e.dance=2.2;e.group.userData.danceStart=performance.now()/1000;rainbowBurst(e.group.position.clone().add(new THREE.Vector3(0,1,0)));}else{burst(e.group.position.clone().add(new THREE.Vector3(0,1,0)),'#9bfff0',18);e.group.position.add(forward.clone().multiplyScalar(.25));}if(e.hp<=0){e.alive=false;setTimeout(()=>{if(e.group.parent)scene.remove(e.group);updateHUD();checkClear()},ultimate?1900:350);combo++;lastHit=performance.now()/1000;tokens+=e.boss?5:1;level=Math.max(level,Math.floor((5-stage)*.2+1));if(e.boss)jewels+=3;}else if(e.boss)toast('The Shogun staggers! Keep blasting!');}}
  updateHUD();save();if(!hit&&!ultimate)toast('Missed! Line up a spirit and BLAST!');}
function checkClear(){if(enemies.some(e=>e.alive))return;playing=false;paused=true;health=Math.min(100,health+20);foodCount+=3;jewels+=stage===5?5:1;tokens+=5;level=Math.min(99,level+1);save();updateHUD();$('result-title').textContent=stage===5?'LUCIFER CAN WAIT!':'CHAPTER CLEARED!';$('result-copy').textContent=stage===5?'The Nightmare Shogun is exorcised. The road to Lucifer starts at Level 67!':'Village saved. Snacks secured. Dignity mostly intact.';$('next-btn').textContent=stage===5?'REPLAY THE ADVENTURE ↻':'NEXT CHAPTER ↗';$('result-panel').classList.remove('hidden');sound(660,.25,'triangle');setTimeout(()=>sound(880,.3,'triangle'),130)}
function damage(amount){if(dodgeCooldown>.6)return;health=Math.max(0,health-amount);updateHUD();sound(115,.2,'sawtooth');toast('Oof! A spirit got a hit in!');if(!health){gameOver=true;playing=false;paused=true;$('result-title').textContent='DOODER NEEDS A NAP';$('result-copy').textContent='The spirits won this round. Your journey is saved.';$('next-btn').textContent='TRY AGAIN';$('result-panel').classList.remove('hidden')}}
function dodge(){if(!playing||paused||dodgeCooldown>0)return;dodgeCooldown=.85;const dir=new THREE.Vector3(joy.x,0,-joy.y);if(dir.length()<.15)dir.set(Math.sin(cameraYaw),0,-Math.cos(cameraYaw));else dir.applyAxisAngle(new THREE.Vector3(0,1,0),cameraYaw);player.position.add(dir.normalize().multiplyScalar(2.4));burst(player.position.clone().add(new THREE.Vector3(0,.8,0)),'#cfb6ff',9);sound(510,.1,'triangle')}
function jump(){if(onGround&&playing&&!paused){jumpVel=6.2;onGround=false;sound(280,.1,'sine')}}
function startGame(){playing=true;paused=false;gameOver=false;$('splash').classList.add('dismissed');$('pause-panel').classList.add('hidden');$('result-panel').classList.add('hidden');makeStage();sound(520,.12,'triangle')}
$('play-btn').onclick=()=>{stage=1;health=100;energy=0;foodCount=0;jewels=0;tokens=0;level=1;save();startGame()};$('continue-btn').onclick=()=>startGame();$('pause-btn').onclick=()=>{if(!playing)return;paused=true;$('pause-panel').classList.remove('hidden')};$('resume-btn').onclick=()=>{$('pause-panel').classList.add('hidden');paused=false};$('restart-btn').onclick=()=>{health=100;energy=0;startGame()};$('next-btn').onclick=()=>{if(gameOver){health=100;energy=0;gameOver=false;startGame();return}if(stage>=5)stage=1;else stage++;save();startGame()};$('back-menu-btn').onclick=()=>{$('result-panel').classList.add('hidden');$('splash').classList.remove('dismissed');paused=true};
$('sound-btn').onclick=()=>{if(audioCtx){audioCtx.suspend();audioCtx=null;$('sound-btn').style.opacity='.45';toast('Sound muted')}else{$('sound-btn').style.opacity='1';sound(440,.1)}};
$('touch-attack').onclick=()=>blast(false);$('touch-ultimate').onclick=()=>blast(true);$('touch-dodge').onclick=dodge;$('touch-jump').onclick=jump;
window.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='Space')jump();if(e.code==='ShiftLeft'||e.code==='ShiftRight')dodge();if(e.code==='KeyE')blast(true);if(e.code==='Escape'&&playing){paused=!paused;$('pause-panel').classList.toggle('hidden',!paused)}if(e.code==='KeyF'||e.code==='Enter')blast(false)});
canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'&&playing&&!paused){mouseDown=true;canvas.setPointerCapture(e.pointerId)}});canvas.addEventListener('pointerup',e=>{if(e.pointerType==='mouse'&&mouseDown){mouseDown=false;blast(false)}});canvas.addEventListener('pointermove',e=>{if(mouseDown){cameraYaw-=e.movementX*.004;camPitch=THREE.MathUtils.clamp(camPitch+e.movementY*.002,-.1,.65)}});
let joyPointer=null;const joyEl=$('joystick'),knob=$('joy-knob');joyEl.addEventListener('pointerdown',e=>{joyPointer=e.pointerId;joyEl.setPointerCapture(joyPointer);moveJoy(e)});joyEl.addEventListener('pointermove',e=>{if(e.pointerId===joyPointer)moveJoy(e)});joyEl.addEventListener('pointerup',e=>{joyPointer=null;joy={x:0,y:0};knob.style.transform='translate(0,0)'});joyEl.addEventListener('pointercancel',()=>{joyPointer=null;joy={x:0,y:0};knob.style.transform='translate(0,0)'});function moveJoy(e){const r=joyEl.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),len=Math.min(36,Math.hypot(dx,dy)),a=Math.atan2(dy,dx),x=Math.cos(a)*len,y=Math.sin(a)*len;joy={x:x/36,y:y/36};knob.style.transform=`translate(${x}px,${y}px)`}

const clock=new THREE.Clock();let damageTimer=0,toastTimer=0;
function update(dt,time){if(!playing||paused)return;attackCooldown=Math.max(0,attackCooldown-dt);dodgeCooldown=Math.max(0,dodgeCooldown-dt);const input=new THREE.Vector3(0,0,0);if(keys.KeyW||keys.ArrowUp)input.z-=1;if(keys.KeyS||keys.ArrowDown)input.z+=1;if(keys.KeyA||keys.ArrowLeft)input.x-=1;if(keys.KeyD||keys.ArrowRight)input.x+=1;input.x+=joy.x;input.z+=joy.y;if(input.length()>1)input.normalize();const move=input.clone().applyAxisAngle(new THREE.Vector3(0,1,0),cameraYaw);player.position.add(move.multiplyScalar(5.2*dt));player.position.x=THREE.MathUtils.clamp(player.position.x,-13,13);player.position.z=THREE.MathUtils.clamp(player.position.z,-13,13);if(input.lengthSq()>.02)player.rotation.y=Math.atan2(move.x,move.z)+Math.PI;
  if(!onGround){player.position.y+=jumpVel*dt;jumpVel-=16*dt;if(player.position.y<=0){player.position.y=0;jumpVel=0;onGround=true}}player.rotation.z=Math.sin(time*12)*.025*(input.lengthSq()>.02?1:0);for(let i=0;i<player.userData.hair.length;i++)player.userData.hair[i].rotation.z=Math.sin(time*5+i*.8)*.055;
  const target=new THREE.Vector3(player.position.x+Math.sin(cameraYaw)*-7,player.position.y+3+camPitch*3,player.position.z+Math.cos(cameraYaw)*7);camera.position.lerp(target,1-Math.pow(.001,dt));camera.lookAt(player.position.x,player.position.y+1.15,player.position.z);camera.fov=THREE.MathUtils.lerp(camera.fov,input.lengthSq()>.1?52:54,dt*2);camera.updateProjectionMatrix();
  for(const p of pickups){if(!p.group.parent)continue;p.group.rotation.y+=dt*1.2;p.group.position.y=.12+Math.sin(time*2.7+p.spin)*.13;if(p.group.position.distanceTo(player.position)<1.15){if(p.bad){health=Math.max(0,health-18);toast('Rotten! Even the demons said “yikes.”');sound(90,.2,'square')}else if(p.kind==='jewel'){jewels++;energy=Math.min(100,energy+20);toast('Spirit jewel! Shiny and digestive.');sound(760,.15,'sine')}else{foodCount++;energy=Math.min(100,energy+35);health=Math.min(100,health+4);toast('Fresh bite! Digestive energy +35');sound(620,.12,'triangle')}burst(p.group.position.clone().add(new THREE.Vector3(0,.4,0)),p.bad?'#8cb65e':'#ffe19a',10);scene.remove(p.group);p.group.parent=null;updateHUD();save();if(!health)damage(0)}}
